import React from "react";
import "./ChatMain.css";

const ChatMain = ({ selectedConversation, messages, newMessage, setNewMessage, handleSend }) => {
  return (
    <div className="chat-main">
      {selectedConversation ? (
        <>
          <div className="chat-header">
            <strong>Conversation with {selectedConversation.username}</strong>
          </div>

          <div className="chat-messages">
            {messages.map((msg, index) => (
              <div
                key={index}
                className={`message-bubble ${msg.fromSelf ? "sent" : "received"}`}
              >
                <div>{msg.text}</div>
                <span className="timestamp">{new Date(msg.createdAt).toLocaleString()}</span>
              </div>
            ))}
          </div>

          <div className="chat-input">
            <input
              type="text"
              placeholder="Type your message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
            />
            <button onClick={handleSend}>Send</button>
          </div>
        </>
      ) : (
        <div className="no-conversation">No conversation selected.</div>
      )}
    </div>
  );
};

export default ChatMain;
